Definition sample_cert_n5 (q : St) : list ngcomp :=
  match q with
  | StA => cert_n5_A | StB => cert_n5_B
  | StC => cert_n5_C | StD => cert_n5_D
  end.

(** The BBB README sample machine, decided by the n-gram closure at
    n = 5 (2264 contexts) with ranking-rule liveness.
    Parameters: window 5, prefix 0, and the generated
    lexicographic certificate. *)
Theorem tm_bbb_sample_never_quasihalts_rank_n5 :
  NeverQuasiHaltsSt (mirror_tm tm_bbb_sample).
Proof.
  apply (ngram_check_neverqh_lex_sound _ 5 0 (150 * 1000) 32 sample_cert_n5).
  vm_compute. reflexivity.
Qed.
